<script setup lang="ts">
import { ref } from 'vue'
import AuthLayout from '@/layouts/AuthLayout.vue'
import http, { getErrorMessage } from '@/api/http'
const email = ref(''); const loading = ref(false); const error = ref(''); const sent = ref(false); const submitted = ref(false)
async function submit() { submitted.value = true; if (!/.+@.+\..+/.test(email.value)) return; loading.value = true; error.value = ''; try { await http.post('/auth/password-reset/request', { email: email.value }); sent.value = true } catch (e) { error.value = getErrorMessage(e) } finally { loading.value = false } }
</script>
<template><AuthLayout><template v-if="sent"><p class="eyebrow">Solicitud enviada</p><h1>Revisa tu correo</h1><p class="intro">Si existe una cuenta asociada a <strong>{{ email }}</strong>, enviaremos las instrucciones de recuperación.</p><p class="notice success">Por seguridad, este mensaje es el mismo para correos registrados y no registrados.</p></template><template v-else><p class="eyebrow">Acceso seguro</p><h1>Recupera tu contraseña</h1><p class="intro">Escribe tu correo y te ayudaremos a recuperar el acceso.</p><p v-if="error" class="notice error">{{ error }}</p><form class="form-stack" novalidate @submit.prevent="submit"><label class="field">Correo electrónico<input v-model.trim="email" class="input no-icon" type="email" placeholder="tu@correo.com" autofocus /><span v-if="submitted && !/.+@.+\..+/.test(email)" class="field-error">Ingresa un correo válido.</span></label><button class="primary-button" type="submit" :disabled="loading">{{ loading ? 'Enviando…' : 'Enviar instrucciones →' }}</button></form></template><div class="form-footer"><span class="subtle">¿Recordaste tu acceso?</span><RouterLink to="/login">Volver a iniciar sesión</RouterLink></div></AuthLayout></template>
